    for r, c in centers:
        for rr, cc in centers:
            if rr == r and cc > c:
                if not any(r2 == r and c < c2 < cc for r2, c2 in centers):
                    for x in range(c + 2, cc - 1):
                        if out[r][x] == 0:
                            out[r][x] = 1
            elif cc == c and rr > r:
                if not any(c2 == c and r < r2 < rr for r2, c2 in centers):
                    for y in range(r + 2, rr - 1):
                        if out[y][c] == 0:
                            out[y][c] = 1
    return out
